{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Naltrexone, which shares the N-cyclopropylmethyl, phenolic 4,5-epoxy morphinan scaffold and differs only by a 6-keto instead of the query's 6-hydroxy, has an absolute oral bioavailability of 5% in humans; the added hydroxyl in the query increases polarity and conjugation liability, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A systemic-availability study in healthy volunteers reports naltrexone oral bioavailability of only 5-6%, confirming that this scaffold is prone to low oral F; this transfers to the more polar 6-hydroxy query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Butorphanol, a related morphinan opioid antagonist with a similar N-cycloalkylmethyl group and phenolic hydroxyl, has absolute oral bioavailability of 5-17% in patients, providing independent support for low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, the 6-methylene analogue, has an absolute oral bioavailability of 41% in humans; this is contradictory evidence, but it lacks the C6 oxygen and is more lipophilic than the query, so it is less directly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Samidorphan, another N-cyclopropylmethyl opioid antagonist, shows 69% absolute oral bioavailability; this is contradictory but has lower structural similarity and a different scaffold, reducing its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low (F < 20%) for 6β-naltrexol. The closest C6-oxygenated analogue naltrexone has low/variable oral bioavailability (often 5-6%), and the query's additional 6-hydroxyl increases polarity and first-pass conjugation risk. High-F analogues such as nalmefene and samidorphan are less transferable because they lack the C6 oxygen or have different scaffolds.",
  "evidence_gaps": [
    "No direct human oral bioavailability data for 6β-naltrexol.",
    "Naltrexone F values vary widely across studies, introducing uncertainty.",
    "Extent of intestinal absorption versus first-pass metabolism for the 6-hydroxy analogue is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

